<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Sorting Algorithm Visualizer</title>
<style>
  :root {
    --bg: #0d1117;
    --panel: #161b22;
    --border: #30363d;
    --text: #e6edf3;
    --muted: #8b949e;
    --accent: #58a6ff;
    --bar: #4c8dff;
    --bar-compare: #f778ba;
    --bar-swap: #f0883e;
    --bar-sorted: #3fb950;
  }
  * { box-sizing: border-box; margin: 0; padding: 0; }
  body {
    background: var(--bg);
    color: var(--text);
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Helvetica, Arial, sans-serif;
    min-height: 100vh;
    display: flex;
    flex-direction: column;
    align-items: center;
    padding: 24px 16px;
  }
  h1 {
    font-size: 1.5rem;
    font-weight: 600;
    margin-bottom: 4px;
    letter-spacing: 0.5px;
  }
  p.sub {
    color: var(--muted);
    font-size: 0.85rem;
    margin-bottom: 20px;
  }
  .controls {
    display: flex;
    gap: 10px;
    margin-bottom: 20px;
    flex-wrap: wrap;
    justify-content: center;
  }
  button {
    background: var(--panel);
    color: var(--text);
    border: 1px solid var(--border);
    border-radius: 6px;
    padding: 8px 20px;
    font-size: 0.95rem;
    cursor: pointer;
    transition: background 0.15s, border-color 0.15s, transform 0.05s;
  }
  button:hover { background: #21262d; border-color: var(--accent); }
  button:active { transform: scale(0.97); }
  button:disabled { opacity: 0.45; cursor: not-allowed; }
  #sort { border-color: var(--accent); color: var(--accent); }
  #sort:hover { background: rgba(88,166,255,0.12); }
  .status {
    font-size: 0.85rem;
    color: var(--muted);
    margin-bottom: 12px;
    min-height: 1.2em;
    font-variant-numeric: tabular-nums;
  }
  #bars {
    display: flex;
    align-items: flex-end;
    justify-content: center;
    gap: 2px;
    width: 100%;
    max-width: 960px;
    height: 340px;
    background: var(--panel);
    border: 1px solid var(--border);
    border-radius: 8px;
    padding: 12px;
  }
  .bar {
    flex: 1 1 auto;
    min-width: 2px;
    background: var(--bar);
    border-radius: 2px 2px 0 0;
    transition: height 0.08s linear, background-color 0.08s linear;
  }
  .bar.compare { background: var(--bar-compare); }
  .bar.swap    { background: var(--bar-swap); }
  .bar.sorted  { background: var(--bar-sorted); }
</style>
</head>
<body>

<h1>Sorting Visualizer</h1>
<p class="sub">Bubble sort &mdash; one comparison per step</p>

<div class="controls">
  <button id="sort">Sort</button>
  <button id="shuffle">Shuffle</button>
  <button id="reset">Reset</button>
</div>

<div class="status" id="status">Ready</div>

<div id="bars"></div>

<script>
(function () {
  "use strict";

  var barsEl = document.getElementById("bars");
  var statusEl = document.getElementById("status");
  var sortBtn = document.getElementById("sort");
  var shuffleBtn = document.getElementById("shuffle");
  var resetBtn = document.getElementById("reset");

  var DEFAULT_SIZE = 40;

  var arr = [];
  var initialArray = [];   // snapshot for reset
  var barEls = [];

  // Bubble-sort stepper state
  var si = 0;              // inner index
  var sn = 0;              // effective unsorted length
  var swappedThisPass = false;
  var comparisons = 0;
  var swaps = 0;

  var animTimer = null;

  function randInt(min, max) {
    return Math.floor(Math.random() * (max - min + 1)) + min;
  }

  function isAscending(a) {
    for (var k = 1; k < a.length; k++) {
      if (a[k - 1] > a[k]) return false;
    }
    return true;
  }

  function resetStepper() {
    si = 0;
    sn = arr.length;
    swappedThisPass = false;
    comparisons = 0;
    swaps = 0;
  }

  function updateStatus(extra) {
    var msg = "Comparisons: " + comparisons + " | Swaps: " + swaps;
    if (extra) msg = extra + "  (" + msg + ")";
    statusEl.textContent = msg;
  }

  function buildBars() {
    barsEl.innerHTML = "";
    barEls = [];
    for (var k = 0; k < arr.length; k++) {
      var d = document.createElement("div");
      d.className = "bar";
      barsEl.appendChild(d);
      barEls.push(d);
    }
    paintBars();
  }

  function paintBars(highlight) {
    var max = 1;
    for (var k = 0; k < arr.length; k++) {
      if (arr[k] > max) max = arr[k];
    }
    var sortedNow = isAscending(arr);
    for (var k = 0; k < arr.length; k++) {
      var el = barEls[k];
      el.style.height = Math.max(2, (arr[k] / max) * 100) + "%";
      var cls = "bar";
      if (highlight) {
        if (highlight.swap && (k === highlight.a || k === highlight.b)) {
          cls += " swap";
        } else if (k === highlight.a || k === highlight.b) {
          cls += " compare";
        } else if (sortedNow) {
          cls += " sorted";
        }
      } else if (sortedNow) {
        cls += " sorted";
      }
      el.className = cls;
    }
  }

  function setArray(a) {
    stopAnimation();
    arr = a.slice();
    initialArray = a.slice();
    resetStepper();
    buildBars();
    updateStatus();
  }

  // One step = one comparison (and a swap when needed).
  // Returns true once the array is fully sorted, false otherwise.
  function sortStep() {
    if (isAscending(arr)) {
      paintBars();
      updateStatus("Sorted!");
      return true;
    }

    if (sn <= 1) {
      // Nothing left to do; array must be sorted (guaranteed for bubble sort).
      paintBars();
      updateStatus("Sorted!");
      return true;
    }

    if (si >= sn - 1) {
      // Start a fresh pass.
      if (!swappedThisPass) {
        // A full pass with no swaps means sorted.
        paintBars();
        updateStatus("Sorted!");
        return true;
      }
      sn--;
      si = 0;
      swappedThisPass = false;
      if (sn <= 1) {
        paintBars();
        updateStatus("Sorted!");
        return true;
      }
    }

    var didSwap = false;
    comparisons++;
    if (arr[si] > arr[si + 1]) {
      var tmp = arr[si];
      arr[si] = arr[si + 1];
      arr[si + 1] = tmp;
      swaps++;
      swappedThisPass = true;
      didSwap = true;
    }
    var a = si, b = si + 1;
    si++;

    paintBars({ a: a, b: b, swap: didSwap });
    updateStatus();

    if (isAscending(arr)) {
      paintBars();
      updateStatus("Sorted!");
      return true;
    }
    return false;
  }

  function stopAnimation() {
    if (animTimer !== null) {
      clearInterval(animTimer);
      animTimer = null;
    }
    sortBtn.disabled = false;
    shuffleBtn.disabled = false;
    resetBtn.disabled = false;
  }

  function startAnimation() {
    if (animTimer !== null) return;
    if (isAscending(arr)) {
      paintBars();
      updateStatus("Already sorted");
      return;
    }
    sortBtn.disabled = true;
    shuffleBtn.disabled = true;
    resetBtn.disabled = true;
    animTimer = setInterval(function () {
      var done = sortStep();
      if (done) stopAnimation();
    }, 40);
  }

  function shuffle() {
    var a = [];
    for (var k = 0; k < DEFAULT_SIZE; k++) a.push(randInt(5, 100));
    // Fisher-Yates shuffle of the values for good measure
    for (var k = a.length - 1; k > 0; k--) {
      var j = Math.floor(Math.random() * (k + 1));
      var tmp = a[k]; a[k] = a[j]; a[j] = tmp;
    }
    setArray(a);
    updateStatus("Shuffled");
  }

  sortBtn.addEventListener("click", startAnimation);
  shuffleBtn.addEventListener("click", shuffle);
  resetBtn.addEventListener("click", function () {
    setArray(initialArray);
    updateStatus("Reset");
  });

  // ---- Programmatic API ----
  window.viz = {
    array: function () {
      return arr.slice();
    },
    setArray: function (a) {
      setArray(a);
    },
    sortStep: function () {
      return sortStep();
    },
    sorted: function () {
      return isAscending(arr);
    }
  };

  // ---- Init ----
  shuffle();
})();
</script>

</body>
</html>
